const intlMap = { "zh-Hans": "zh-CN", "zh-Hant": "zh-TW", "pt-BR": "pt-BR", ur: "ur", uk: "uk" };
export const intlLocale = (locale) => intlMap[locale] ?? locale;

function text(locale) {
  return LOCALIZED[locale] || LOCALIZED[String(locale || "").split(/[-_]/)[0]] || LOCALIZED.en;
}

export function v2ShellCopy(locale = "en") {
  return text(locale);
}
